mapper.select:
select f.id as form_id, f.code, f.title, f.description, f.closing_text, f.total_questions, f.status, f.create_time, count(a.id) as sent_count, sum(case when a.status = 1 then 1 else 0 end) as answered_count from survey_form f left join survey_assignment a on a.form_id = f.id
and f.title like concat('%', #{title}, '%') and f.status = #{status}
group by f.id, f.code, f.title, f.description, f.closing_text, f.total_questions, f.status, f.create_time order by f.id desc

select count(1)
from survey_assignment
where form_id = #{formId} and lecture_id = #{lectureId} and user_info_id = #{userInfoId}

mapper.update:
update survey_assignment
set status = 1, submission_id = #{submissionId}, submitted_at = #{submittedAt}, update_time = #{submittedAt}
where id = #{assignmentId}

mapper.select:
select a.id as assignment_id, a.form_id, l.id as course_id, l.name as course_name, u.id as user_info_id, u.user_name, u.real_name, u.phone, a.status, case when a.status = 1 then '已提交' else '未提交' end as status_label, a.assigned_at, a.submitted_at from survey_assignment a join lectures l on l.id = a.lecture_id join user_info u on u.id = a.user_info_id where a.form_id = #{formId} and a.lecture_id = #{lectureId} and a.status = #{status}
and (u.phone like concat('%', #{keyword}, '%') or u.real_name like concat('%', #{keyword}, '%') or u.user_name like concat('%', #{keyword}, '%'))
order by a.id desc
